// Draw two circles, one on the leftmost side of the screen and one on the rightmost side. Animate the two circles to move towards each other, and when they are collding, change the color of the circles.

const canvas = document.getElementById("my-canvas");
const ctx = canvas.getContext("2d");
canvas.width = 800;
canvas.height = 500;

let circle1 = { x: 50, y: 250, size: 20 };
let circle2 = { x: 500, y: 250, size: 20 };

const drawCircles = () => {
  ctx.beginPath();
  ctx.arc(circle1.x, circle1.y, circle1.size, 0, Math.PI * 2, false);
  ctx.fill();
  ctx.closePath();

  ctx.beginPath();
  ctx.arc(circle2.x, circle2.y, circle2.size, 0, Math.PI * 2, false);
  ctx.fill();
  ctx.closePath();
}

const draw = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  circle1.x += 1;
  circle2.x -= 1;

  ctx.fillStyle = "black";
  console.log(Math.abs(circle1.x - circle2.x));
  if (Math.abs(circle1.x - circle2.x) < circle1.size + circle2.size) {
    ctx.fillStyle = "blue";
  }

  drawCircles();
}

setInterval(draw, 10);

// Draw two rectangles of random width and height onto the canvas. If the two rectangles are touching, display “the rectangles are colliding” on the canvas.

const canvas = document.getElementById('my-canvas');
const ctx = canvas.getContext('2d');
canvas.width = 550;
canvas.height = 500;

const drawRandomRectangle = () => {
  let cornerX = Math.floor(Math.random() * 450) + 50;
  let cornerY = Math.floor(Math.random() * 400) + 50;

  let height = Math.floor(Math.random() * 200) + 100;
  let width = Math.floor(Math.random() * 200) + 100;

  let r = Math.floor(Math.random() * 255);
  let g = Math.floor(Math.random() * 255);
  let b = Math.floor(Math.random() * 255);

  ctx.fillStyle = `rgb(${r}, ${g}, ${b})`
  ctx.fillRect(cornerX, cornerY, width, height);

  return {x: cornerX, y: cornerY, width: width, height: height};
}

const checkCollision = (rect1, rect2) => {
  let colliding = false;
  if (rect1.x + rect1.width > rect2.x && rect1.x < rect2.x + rect2.width){
    if(rect1.y + rect1.height > rect2.y && rect1.y < rect2.y + rect2.height ){
      colliding = true;
    }
  }
  return colliding;
}



let rect1 = drawRandomRectangle();
let rect2 = drawRandomRectangle();

ctx.fillStyle = "black";

if (checkCollision(rect1, rect2)){
  ctx.font = "30px Arial";
  ctx.textAlign = "center";
  ctx.fillText("The rectangles are colliding!", canvas.width/2, 100);
}

