// Animate a ball which bounces around the canvas. The ball should lose speed every time it hits a wall until it ultimately comes to a rest.

var canvas = document.getElementById("my-canvas");
var ctx = canvas.getContext("2d");

var x = canvas.width/2;
var y = canvas.height-30;
var size = 15;

var dx = 2;
var dy = -5;

const drawBall = () => {
  ctx.beginPath();
  ctx.arc(x, y, size, 0, Math.PI*2, false);
  ctx.fillStyle = "green";
  ctx.fill();
  ctx.closePath();
}

const draw = () => {
  ctx.clearRect(0,0, canvas.width, canvas.height);
  drawBall();
  if (y + dy < size ){
    dy = -dy;
  }
  if(y + dy > canvas.height - size){
    dy = -dy * 0.8; 
    dx = dx * 0.8;
  }
  if (x + dx > canvas.width - size || x + dx < size){
    dx = -dx * 0.8;
  }

  if (dx < 0.1 && dx > -0.1 && dy < 0.1 && dy > -0.1){
    dx = 0;
    dy = 0;
  }

  x+=dx;
  y+=dy;
  //size+=dsize;
  dy+=.08;
}

